use std::collections::HashMap;

fn solve(cafes: Vec<i8>) -> i8 {
    // Compute the last occurrence index for each cafe value.
    let mut last_positions: HashMap<i8, usize> = HashMap::new();
    for (i, &cafe) in cafes.iter().enumerate() {
        last_positions.insert(cafe, i);
    }

    // Find the cafe whose last occurrence index is minimal.
    // We know cafes is non-empty, so we can initialize from the first element.
    let mut answer = cafes[0];
    let mut min_pos = *last_positions.get(&answer).unwrap();

    for (&cafe, &pos) in last_positions.iter() {
        if pos < min_pos {
            min_pos = pos;
            answer = cafe;
        }
    }

    answer
}

fn exec_last_occurrence_position(cafes: &Vec<i8>, cafe: i8) -> usize {
    let mut last = 0;
    for (i, &val) in cafes.iter().enumerate() {
        if val == cafe {
            last = i;
        }
    }
    last
}

